const fs = require('node:fs')
const path = require('node:path')

// A third-party watch plugin: a key of its own, a run that asks for a rerun, a filter on which
// test files run, and a file-change hook. It writes what it saw to plugin.jsonl beside itself.
class CustomPlugin {
  constructor({ config }) {
    this.log = path.join(__dirname, 'plugin.jsonl')
    this.skip = (config && config.skip) || 'skipped'
  }

  write(entry) {
    fs.appendFileSync(this.log, `${JSON.stringify(entry)}\n`)
  }

  apply(hooks) {
    hooks.shouldRunTestSuite(({ testPath }) => !path.basename(testPath).startsWith(this.skip))
    hooks.onFileChange(({ projects }) => {
      const files = projects.flatMap((project) =>
        project.testPaths.map((file) => path.relative(project.config.rootDir, file)),
      )
      this.write({ onFileChange: files.sort() })
    })
  }

  getUsageInfo() {
    return { key: 'x', prompt: 'run the custom plugin' }
  }

  run() {
    this.write({ run: true })
    return Promise.resolve(true)
  }
}

module.exports = CustomPlugin
